+    return () => {
+      cancelled = true;
+      clearTimeout(timeout);
+      finish(false, 'released');
+      // Release this UI's owner, never globally disconnect another open surface.
+      release();
+      manager.cleanupPrewarm();
+      manager.clearAllCaches();
+    };
